import{_ as e,o as d,c as o,a3 as a}from"./chunks/framework.C8DWDwzR.js";const m=JSON.parse('{"title":"Agent skills","description":"","frontmatter":{},"headers":[],"relativePath":"docs/agents/skills.md","filePath":"docs/agents/skills.md"}'),s={name:"docs/agents/skills.md"};function i(r,t,n,c,l,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="agent-skills" tabindex="-1">Agent skills <a class="header-anchor" href="#agent-skills" aria-label="Permalink to &quot;Agent skills&quot;">​</a></h1><p>A skill is a short set of instructions an agent follows for one kind of task: refining an issue, writing a test first, diagnosing a bug. The skills for this repo live in <code>.agents/skills/</code>, one folder per skill, and both Codex and Claude Code read them. This page is the map: which skill to use when, and an example of asking for it.</p><p>This page is updated in the same PR whenever a skill is added, renamed or removed. A skill that is missing here is not finished.</p><h2 id="how-a-skill-gets-used" tabindex="-1">How a skill gets used <a class="header-anchor" href="#how-a-skill-gets-used" aria-label="Permalink to &quot;How a skill gets used&quot;">​</a></h2><p>There are two ways a skill runs.</p><ul><li><strong>Chosen by the agent.</strong> The skill&#39;s description tells the agent when it fits, and the agent loads it on its own. Most skills work this way. You can also name one (&quot;use the tdd skill&quot;).</li><li><strong>Command only.</strong> The skill&#39;s frontmatter sets <code>disable-model-invocation: true</code>, so the agent never picks it up by itself. You start it by name, with <code>/name</code> in Claude Code (for example <code>/grill-me</code>). Use this for steps that should run only when you ask, such as publishing a spec or triaging the tracker.</li></ul><p>An agent that has already loaded a skill follows its instructions and does not need to be reminded. Skills that the agent should always read before a kind of work are listed in <code>CLAUDE.md</code> under &quot;Agent skills&quot;.</p><h2 id="start-here-the-issue-to-pr-flow" tabindex="-1">Start here: the issue-to-PR flow <a class="header-anchor" href="#start-here-the-issue-to-pr-flow" aria-label="Permalink to &quot;Start here: the issue-to-PR flow&quot;">​</a></h2><p>Most work follows the path in <a href="./../../CONTRIBUTING">CONTRIBUTING</a>. The skills map onto it like this:</p><table tabindex="0"><thead><tr><th>Step</th><th>Skill</th><th>Example</th></tr></thead><tbody><tr><td>A rough idea needs to become an agent-ready issue</td><td><code>refine-issue</code></td><td>&quot;refine #42&quot;</td></tr><tr><td>Issues need a state and labels</td><td><code>triage-issues</code> (or <code>triage</code>, command only)</td><td>&quot;triage the open issues&quot;</td></tr><tr><td>The conversation becomes a spec on the tracker</td><td><code>to-spec</code> (command only)</td><td><code>/to-spec</code></td></tr><tr><td>The spec is cut into tickets</td><td><code>to-tickets</code> (command only)</td><td><code>/to-tickets</code></td></tr><tr><td>The work is built</td><td><code>implement</code> or <code>implement-spec</code> (command only), or <code>coach-poulpy-implement</code></td><td><code>/implement-spec</code></td></tr><tr><td>The change is reviewed before the PR</td><td><code>code-review</code></td><td>&quot;review since main&quot;</td></tr><tr><td>The PR body is written</td><td><code>pr</code></td><td>&quot;write the PR body&quot;</td></tr><tr><td>The issue tracker is read or changed</td><td><code>issue-tracker</code></td><td>&quot;list the open issues about exercises&quot;</td></tr></tbody></table><h2 id="skill-reference" tabindex="-1">Skill reference <a class="header-anchor" href="#skill-reference" aria-label="Permalink to &quot;Skill reference&quot;">​</a></h2><h3 id="workflow-and-tracker" tabindex="-1">Workflow and tracker <a class="header-anchor" href="#workflow-and-tracker" aria-label="Permalink to &quot;Workflow and tracker&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Skill</th><th>Use it when</th><th>Example</th></tr></thead><tbody><tr><td><code>issue-tracker</code></td><td>Creating, reading, refining or updating issues and PRs on GitHub</td><td>&quot;open an issue for the rest timer&quot;</td></tr><tr><td><code>refine-issue</code></td><td>A rough issue needs a brief an agent can build from, without widening it</td><td>&quot;refine #58&quot;</td></tr><tr><td><code>triage-issues</code></td><td>Moving issues through the repo&#39;s states and labels</td><td>&quot;triage the new issues&quot;</td></tr><tr><td><code>triage</code> (command only)</td><td>The same triage, as a state machine with roles and briefs</td><td><code>/triage</code></td></tr><tr><td><code>to-spec</code> (command only)</td><td>Turning what was just discussed into a spec, with no interview</td><td><code>/to-spec</code></td></tr><tr><td><code>to-tickets</code> (command only)</td><td>Splitting a plan or spec into tracer-bullet tickets that block each other</td><td><code>/to-tickets</code></td></tr><tr><td><code>to-questionnaire</code> (command only)</td><td>A decision cannot be settled by an agent, so someone else must answer</td><td><code>/to-questionnaire</code></td></tr><tr><td><code>wayfinder</code> (command only)</td><td>A huge piece of work, too big for one session, needs a shared map of decisions</td><td><code>/wayfinder</code></td></tr><tr><td><code>pr</code></td><td>Writing a pull request body from the template</td><td>&quot;write the PR body&quot;</td></tr><tr><td><code>setup-matt-pocock-skills</code> (command only)</td><td>Once per repo: set the tracker, label vocabulary and domain doc layout</td><td><code>/setup-matt-pocock-skills</code></td></tr></tbody></table><h3 id="building-and-checking-code" tabindex="-1">Building and checking code <a class="header-anchor" href="#building-and-checking-code" aria-label="Permalink to &quot;Building and checking code&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Skill</th><th>Use it when</th><th>Example</th></tr></thead><tbody><tr><td><code>coach-poulpy-implement</code></td><td>Building a well-scoped issue or approved change in this repo, with its tests and checks</td><td>&quot;implement #61&quot;</td></tr><tr><td><code>implement</code> (command only)</td><td>Building work from a spec or tickets, with TDD at agreed seams</td><td><code>/implement</code></td></tr><tr><td><code>implement-spec</code> (command only)</td><td>Building what <code>to-spec</code> and <code>to-tickets</code> produced</td><td><code>/implement-spec</code></td></tr><tr><td><code>tdd</code></td><td>Writing a feature or fix test first, red then green</td><td>&quot;fix the rest timer test-first&quot;</td></tr><tr><td><code>diagnosing-bugs</code></td><td>Something is broken, throwing, failing or slow, and the cause is unknown</td><td>&quot;debug why the set counter resets&quot;</td></tr><tr><td><code>code-review</code></td><td>Checking a change against the repo&#39;s standards and the issue it answers</td><td>&quot;review this branch against #61&quot;</td></tr><tr><td><code>code-graph</code></td><td>Finding what a symbol touches before editing it</td><td>&quot;what calls <code>WorkoutEngine.next</code>?&quot;</td></tr><tr><td><code>prototype</code></td><td>A design or state question needs a throwaway experiment</td><td>&quot;prototype the interval state model&quot;</td></tr><tr><td><code>wizard</code> (command only)</td><td>A human must walk through steps only they can do, such as adding a secret</td><td>&quot;make a wizard for the Play Console key&quot;</td></tr></tbody></table><h3 id="understanding-the-domain-and-architecture" tabindex="-1">Understanding the domain and architecture <a class="header-anchor" href="#understanding-the-domain-and-architecture" aria-label="Permalink to &quot;Understanding the domain and architecture&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Skill</th><th>Use it when</th><th>Example</th></tr></thead><tbody><tr><td><code>area-guidance</code></td><td>A task touches an area and you need its rules (model, screens, Poulpy, translations)</td><td>&quot;what rules apply to the translations?&quot;</td></tr><tr><td><code>domain-context</code></td><td>Before proposing a change to domain behaviour, to use the glossary&#39;s words</td><td>&quot;is &#39;set&#39; the right word here?&quot;</td></tr><tr><td><code>domain-modeling</code></td><td>Writing or editing <code>CONTEXT.md</code> or an ADR</td><td>&quot;record this decision as an ADR&quot;</td></tr><tr><td><code>codebase-design</code></td><td>Designing a module&#39;s interface or deciding where a seam goes</td><td>&quot;where should the test seam for the engine go?&quot;</td></tr><tr><td><code>improve-codebase-architecture</code> (command only)</td><td>Scanning for modules that could be deeper, then grilling on one</td><td><code>/improve-codebase-architecture</code></td></tr><tr><td><code>grilling</code></td><td>Stress-testing a plan or idea with relentless questions</td><td>&quot;grill me on this plan&quot;</td></tr><tr><td><code>grill-me</code> (command only)</td><td>The same interview, as a command</td><td><code>/grill-me</code></td></tr><tr><td><code>grill-with-docs</code> (command only)</td><td>An interview that also writes ADRs and glossary entries as it goes</td><td><code>/grill-with-docs</code></td></tr><tr><td><code>research</code></td><td>Gathering facts from primary sources into a Markdown file in the repo</td><td>&quot;research the Wear OS heart-rate API&quot;</td></tr></tbody></table><h3 id="sessions-hand-offs-and-writing" tabindex="-1">Sessions, hand-offs and writing <a class="header-anchor" href="#sessions-hand-offs-and-writing" aria-label="Permalink to &quot;Sessions, hand-offs and writing&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Skill</th><th>Use it when</th><th>Example</th></tr></thead><tbody><tr><td><code>handoff</code> (command only)</td><td>Packing the conversation into a document for a fresh agent</td><td><code>/handoff the next session writes the server tests</code></td></tr><tr><td><code>claude-handoff</code> (command only)</td><td>Handing the conversation to a background agent that starts at once</td><td><code>/claude-handoff</code></td></tr><tr><td><code>chief-of-staff</code> (command only)</td><td>One long goal, coordinated across subagents in a single session</td><td><code>/chief-of-staff</code></td></tr><tr><td><code>retro</code> (command only)</td><td>A retrospective on a finished session</td><td><code>/retro</code></td></tr><tr><td><code>teach</code> (command only)</td><td>Learning a skill or concept inside this workspace</td><td><code>/teach kotlin flows</code></td></tr><tr><td><code>loop-me</code> (command only)</td><td>Grilling on specs for a workflow to build</td><td><code>/loop-me</code></td></tr><tr><td><code>wait-what</code> (command only)</td><td>A message did not land, so it is re-pitched</td><td><code>/wait-what</code></td></tr><tr><td><code>writing-for-agents</code></td><td>Creating or editing a skill, <code>AGENTS.md</code> or <code>CLAUDE.md</code></td><td>&quot;tighten the CLAUDE.md house rules&quot;</td></tr></tbody></table><h3 id="web-vue-and-server-code" tabindex="-1">Web, Vue and server code <a class="header-anchor" href="#web-vue-and-server-code" aria-label="Permalink to &quot;Web, Vue and server code&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Skill</th><th>Use it when</th><th>Example</th></tr></thead><tbody><tr><td><code>daisyui</code></td><td>Writing any HTML or JSX with DaisyUI classes (always read it for web UI)</td><td>&quot;add a card to the landing page&quot;</td></tr><tr><td><code>vue-best-practices</code></td><td>Any Vue, <code>.vue</code>, Vue Router, Pinia or Vite work (always read it for web UI)</td><td>&quot;add a route for the workout page&quot;</td></tr><tr><td><code>vue-router-best-practices</code></td><td>Route params, navigation guards, route lifecycle</td><td>&quot;guard the admin route&quot;</td></tr><tr><td><code>vue-pinia-best-practices</code></td><td>A Pinia store, its state or its reactivity</td><td>&quot;move the session state into a store&quot;</td></tr><tr><td><code>vue-testing-best-practices</code></td><td>Vitest, Vue Test Utils or Playwright tests</td><td>&quot;test the login form&quot;</td></tr><tr><td><code>vue-debug-guides</code></td><td>A Vue runtime error, warning, async failure or hydration issue</td><td>&quot;why does this component warn?&quot;</td></tr><tr><td><code>vue-jsx-best-practices</code></td><td>JSX syntax inside Vue</td><td>&quot;convert this to JSX&quot;</td></tr><tr><td><code>vue-options-api-best-practices</code></td><td>Only when a file uses the Options API</td><td>&quot;fix this options-API component&quot;</td></tr><tr><td><code>create-adaptable-composable</code></td><td>Writing a composable that takes plain values, refs or getters</td><td>&quot;make <code>useTimer</code> accept a ref&quot;</td></tr><tr><td><code>http4k-development</code></td><td>Any http4k module on the server</td><td>&quot;add a route to the sync server&quot;</td></tr></tbody></table><h2 id="what-to-do-when-a-skill-is-missing" tabindex="-1">What to do when a skill is missing <a class="header-anchor" href="#what-to-do-when-a-skill-is-missing" aria-label="Permalink to &quot;What to do when a skill is missing&quot;">​</a></h2><p>If a skill you expect is not listed by your agent, check two things. First, is it on this page? Second, is it committed under <code>.agents/skills/</code> with a <code>SKILL.md</code> that has a <code>name</code> matching its folder? A skill that is committed but still missing from a running session usually means the session started before it was added: start a new session.</p><h2 id="adding-or-changing-a-skill" tabindex="-1">Adding or changing a skill <a class="header-anchor" href="#adding-or-changing-a-skill" aria-label="Permalink to &quot;Adding or changing a skill&quot;">​</a></h2><ol><li>Create the folder under <code>.agents/skills/&lt;name&gt;/</code> with a <code>SKILL.md</code>. Do not edit the copies under <code>.claude/skills/</code>; they are symlinks.</li><li>Give it a <code>description</code> that says when to use it. Add <code>disable-model-invocation: true</code> only when the skill should run solely on request.</li><li>Add a row to the table above, in the group that fits, with a short example. Update this page in the same PR.</li><li>Run the skill once in a fresh session to check it loads.</li></ol>',25)])])}const g=e(s,[["render",i]]);export{m as __pageData,g as default};
